Here are the MSTest comparison assertions perfect for your `ScoreCalculator` boundary tests:

## Comparison Assertions (MSTest 3.x+)

```csharp
Assert.IsGreaterThan(lowerBound, actual);   // actual > lowerBound
Assert.IsLessThan(upperBound, actual);      // actual < upperBound
Assert.IsInRange(actual, low, high);        // low <= actual <= high
```

## Example Tests for Your ScoreCalculator

```csharp
[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calculator = new();

    [TestMethod]
    [DataRow(9, 10)]
    [DataRow(10, 10)]
    public void CalculatePercentage_HighScores_ReturnsAtLeast90(int correct, int total)
    {
        var result = _calculator.CalculatePercentage(correct, total);

        Assert.IsInRange(result, 90.0, 100.0);
    }

    [TestMethod]
    public void CalculatePercentage_PartialScore_ReturnsBetween0And100()
    {
        var result = _calculator.CalculatePercentage(7, 10);

        Assert.IsGreaterThan(0.0, result);
        Assert.IsLessThan(100.0, result);
    }

    [TestMethod]
    [DataRow(90.0, "A")]
    [DataRow(89.99, "B")]
    [DataRow(80.0, "B")]
    [DataRow(79.99, "C")]
    [DataRow(70.0, "C")]
    [DataRow(69.99, "D")]
    [DataRow(60.0, "D")]
    [DataRow(59.99, "F")]
    public void GetGrade_AtBoundary_ReturnsCorrectGrade(double percentage, string expected)
    {
        var grade = _calculator.GetGrade(percentage);

        Assert.AreEqual(expected, grade);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_CapsAt100()
    {
        var result = _calculator.NormalizeScore(150.0, 100.0);

        Assert.AreEqual(100.0, result);
    }

    [TestMethod]
    public void NormalizeScore_ValidInput_ReturnsInRange()
    {
        var result = _calculator.NormalizeScore(75.0, 100.0);

        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(5, 0));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(11, 10));
    }
}
```

## Key Takeaways

| Scenario | Assertion |
|----------|-----------|
| Value within bounds | `Assert.IsInRange(actual, low, high)` |
| Value above threshold | `Assert.IsGreaterThan(lowerBound, actual)` |
| Value below ceiling | `Assert.IsLessThan(upperBound, actual)` |
| Exact boundary value | `Assert.AreEqual(expected, actual)` |
| Invalid input throws | `Assert.ThrowsExactly<T>(() => ...)` |

These produce clear failure messages like *"Expected value to be in range [0, 100] but was 105"* — far better than `Assert.IsTrue(x >= 0 && x <= 100)`.
